class Box { public int N; }
record Value {
 public required string Name { get; set; }
 public int Stored;
 public Box Box { get; init; } = MakeBox();
 public int Number { get => Stored; init { Print("set:" + value); Stored = value + 1; } }
 public Value() { Print("constructor"); }
 static Box MakeBox() { Print("field"); return new Box { N = 1 }; }
}
Value Source(Value value) { Print("receiver"); return value; }
int Change(Value value) { Print("rhs"); value.Stored = 40; return 7; }
void Main() {
 var original = new Value { Name = "Ada", Stored = 2 };
 var copy = Source(original) with { Number = Change(original), Name = "Grace" };
 Print(original.Name + ":" + original.Stored); Print(copy.Name + ":" + copy.Stored);
 copy.Box.N = 9; Print(original.Box.N);
 var second = original with { Name = (original.Name = "Updated") };
 Print(second.Stored); Print(second.Name); Print(copy.Name);
}
